package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.uiapi.*;
import dev.tacticalcombat.rules.srd.*;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;

/** Compact shared sheet/review. Only the final equipment block grows with record count. */
public final class CharacterSheetUi {
    public interface Actions {
        boolean healthEditable(); boolean trackable(String section);
        void health(String key,int delta); void track(RpgRecords.Change change);
        void inspect(FeatureReference.Entry entry); void encounters(); boolean campaign();
        default boolean inspirationAwardable(){return !campaign();}
        default void resources(){}
    }
    public record Layout(int headerHeight,int abilityColumns,int abilityHeight,int statColumns,int statHeight,int trackerHeight,int saveHeight,int detailColumns,int detailHeight,int equipmentTop){}
    public static Layout layout(int width){int w=width-12,ac=w>=420?6:w>=240?3:2,sc=w>=420?6:w>=240?3:2,dc=w>=550?3:w>=300?2:1,header=w>=350?48:64,ah=((6+ac-1)/ac)*32,sh=((6+sc-1)/sc)*32,th=w>=400?24:46,save=w>=350?26:44,dh=((3+dc-1)/dc)*43;return new Layout(header,ac,ah,sc,sh,th,save,dc,dh,6+header+ah+sh+th+save+dh+4);}
    private CharacterSheetUi(){}
    public static List<UiLayout.Rect> columns(int width,int y,int count,int height){int cols=width>=620?Math.min(count,3):width>=300?Math.min(count,2):1,gap=8,cw=(width-12-gap*(cols-1))/cols;var out=new ArrayList<UiLayout.Rect>();for(int i=0;i<count;i++)out.add(new UiLayout.Rect(6+i%cols*(cw+gap),y+i/cols*(height+gap),cw,height));return List.copyOf(out);}
    public static void build(CharacterCanvas pane,JsonObject snapshot,boolean library,Actions actions,JsonObject validation,JsonObject encounter){int x=6,w=pane.getWidth()-12,y=6;var layout=layout(pane.getWidth());JsonObject sheet=snapshot.getAsJsonObject("sheet"),identity=SheetSections.read(sheet,"identity"),trackers=SheetSections.read(sheet,"trackers");var xp=DashboardModel.xp(sheet);boolean narrow=w<350;
        pane.panel("",x,y,w,layout.headerHeight()-3);pane.skinHead(library?"":text(snapshot,"owner"),x+4,y+4,20);pane.label(text(snapshot,"name")+" · Level "+xp.level()+" · "+xp.value()+" XP",x+29,y+3,w-34,RpgTheme.GOLD);pane.label(shown(text(identity,"species"))+" · "+shown(text(identity,"characterClass"))+(text(identity,"subclass").isBlank()?"":" / "+text(identity,"subclass")),x+29,y+17,w-34,RpgTheme.TEXT);String physical="Age "+shown(text(identity,"age"))+" · Height "+shown(text(identity,"height"));pane.label(physical+(narrow?"":" · "+shown(text(identity,"alignment"))),x+4,y+31,w-8,RpgTheme.MUTED);if(narrow)pane.label(shown(text(identity,"alignment")),x+4,y+45,w-8,RpgTheme.MUTED);y+=layout.headerHeight();
        List<String> keys=CreatorDraftState.ABILITIES;int cw=(w-4*(layout.abilityColumns()-1))/layout.abilityColumns();JsonObject scores=null;try{scores=SrdAuthoring.data(sheet).getAsJsonObject("abilities");}catch(RuntimeException ignored){}for(int i=0;i<6;i++){String key=keys.get(i);int ax=x+i%layout.abilityColumns()*(cw+4),ay=y+i/layout.abilityColumns()*32;pane.panel("",ax,ay,cw,28);pane.icon(key,ax+4,ay+5,12);pane.label(key.toUpperCase(Locale.ROOT),ax+19,ay+3,cw-22,RpgTheme.MUTED);String value=scores==null?"—":text(scores,key)+" ("+signed(WizardModel.modifier(scores.get(key).getAsInt()))+")";pane.label(value,ax+5,ay+15,cw-10,RpgTheme.GOLD);}y+=layout.abilityHeight();
        var stats=DashboardModel.combat(snapshot,library);cw=(w-4*(layout.statColumns()-1))/layout.statColumns();String[] labels={"HP / Max","Temp HP","AC","Initiative","Speed","Prof"};for(int i=0;i<6;i++){int sx=x+i%layout.statColumns()*(cw+4),sy=y+i/layout.statColumns()*32;pane.panel("",sx,sy,cw,28);pane.label(labels[i],sx+4,sy+3,cw-8,RpgTheme.MUTED);String value=i<stats.size()?stats.get(i).value():"—";if(i<2&&actions!=null){String key=i==0?"hp":"temporary_hp";int current=0,max=0;try{var data=SrdAuthoring.data(sheet);current=data.get(key).getAsInt();max=i==0?data.get("hp_max").getAsInt():1024;}catch(RuntimeException ignored){}var minus=pane.control("health:"+key+":-",new RpgButton(sx+2,sy+13,12,13,"−","",()->actions.health(key,-1)).accessible("Decrease "+labels[i]).hint(library?"Edit the independent library HP record":"Campaign HP is authoritative; use authorized encounter controls"));var plus=pane.control("health:"+key+":+",new RpgButton(sx+cw-14,sy+13,12,13,"+","",()->actions.health(key,1)).accessible("Increase "+labels[i]).hint(library?"Cannot exceed maximum; temporary HP stays separate":"Campaign HP is authoritative; use authorized encounter controls"));minus.active=actions.healthEditable()&&current>0;plus.active=actions.healthEditable()&&current<max;pane.label(value,sx+16,sy+15,cw-32,RpgTheme.TEXT);}else pane.label(value,sx+4,sy+15,cw-8,RpgTheme.TEXT);}y+=layout.statHeight();
        int inspiration=trackers.get("inspiration").getAsInt();pane.label("Inspiration "+inspiration,x+2,y+5,111,RpgTheme.GOLD);counter(pane,actions,"inspiration",RpgRecords.Action.INSPIRATION,inspiration,0,Integer.MAX_VALUE,x+114,y,actions!=null&&actions.inspirationAwardable());int dx=w>=400?x+229:x+66,dy=w>=400?y:y+23;pane.label("Death Saves",w>=400?x+162:x+2,dy+5,65,RpgTheme.MUTED);for(int type=0;type<2;type++){boolean success=type==0;String key=success?"deathSuccesses":"deathFailures";int value=trackers.get(key).getAsInt(),bx=dx+type*75;pane.label(success?"S":"F",bx,dy+5,12,RpgTheme.MUTED);for(int i=1;i<=3;i++){int target=i,px=bx+14+(i-1)*19;if(actions!=null){var pip=pane.control(key+i,new RpgButton(px,dy,18,18,i<=value?"●":"○","",()->actions.track(new RpgRecords.Change(success?RpgRecords.Action.DEATH_SUCCESSES:RpgRecords.Action.DEATH_FAILURES,"trackers","",0,target==value?target-1:target))).accessible((success?"Death success ":"Death failure ")+i));pip.active=actions.trackable("trackers");}else pane.label(i<=value?"●":"○",px,dy+5,18,RpgTheme.TEXT);}}y+=layout.trackerHeight();
        pane.label("Saving Throws",x+2,y,w,RpgTheme.GOLD);int saveCols=w>=350?6:3;cw=(w-4*(saveCols-1))/saveCols;var checks=ProficiencyModel.checks(snapshot,true);for(int i=0;i<6;i++){String key=keys.get(i);var c=checks.stream().filter(a->a.ability().equals(key)).findFirst().orElseThrow();pane.label(key.toUpperCase(Locale.ROOT)+" "+(ProficiencyModel.hasScores(snapshot)?signed(c.total()):"—")+(c.proficient()?" P":""),x+i%saveCols*(cw+4)+2,y+13+i/saveCols*16,cw-4,RpgTheme.TEXT);}y+=layout.saveHeight();
        cw=(w-6*(layout.detailColumns()-1))/layout.detailColumns();for(int i=0;i<3;i++){int sx=x+i%layout.detailColumns()*(cw+6),sy=y+i/layout.detailColumns()*43;pane.panel("",sx,sy,cw,39);if(i==0){pane.label("Combat & Actions",sx+4,sy+3,cw-8,RpgTheme.GOLD);String description=combatInformation(sheet,encounter,snapshot);var entry=new FeatureReference.Entry("sheet:combat","Combat & Actions","Existing profile",0,"","Existing encounter controls","","","",description,"INFORMATIONAL",description);var b=pane.control("combat:inspect",new RpgButton(sx+3,sy+16,cw-(actions!=null&&actions.campaign()?29:6),19,combatNames(sheet),"",()->{if(actions!=null)actions.inspect(entry);}).hint(description));b.active=actions!=null;if(actions!=null&&actions.campaign())pane.control("combat:encounters",new RpgButton(sx+cw-23,sy+16,20,19,"→","",actions::encounters).accessible("Open encounter controls").hint("Open existing authorized encounter controls"));}else if(i==1){pane.label("Cond: "+conditions(sheet)+" · Exh "+text(trackers,"exhaustion"),sx+4,sy+3,cw-8,RpgTheme.GOLD);String summary=resourceSummary(trackers)+" · "+conditions(sheet);var b=pane.control("resources:inspect",new RpgButton(sx+3,sy+16,cw-6,19,resourceSummary(trackers),"",()->{if(actions!=null)actions.resources();}).hint(summary+"\nManual markers; no automatic effects."));b.active=actions!=null;}else{pane.label("Notable Features",sx+4,sy+3,cw-8,RpgTheme.GOLD);var features=notable(sheet);String title=features.isEmpty()?"No features recorded":features.getFirst().name()+(features.size()>1?" +"+(features.size()-1):"");var b=pane.control("features:inspect",new RpgButton(sx+3,sy+16,cw-6,19,title,"",()->{if(actions!=null&&!features.isEmpty())actions.inspect(features.getFirst());}).hint(features.stream().map(FeatureReference.Entry::name).reduce((a,b2)->a+"\n"+b2).orElse("No recorded features")));b.active=actions!=null&&!features.isEmpty();}}
        y=layout.equipmentTop();
        // Blocking errors stay above equipment; they grow only on invalid pre-finalization review.
        if(validation!=null)for(var raw:array(validation,"errors")){var issue=raw.getAsJsonObject();String line=CreatorFlow.errorStep(text(issue,"section")).title+": "+text(issue,"message");pane.wrapped(line,x,y,w,RpgTheme.ERROR);y+=net.minecraft.client.MinecraftClient.getInstance().textRenderer.getTextHandler().wrapLines(line,w,net.minecraft.text.Style.EMPTY).size()*12+3;}
        pane.label("Equipment Summary",x+2,y,w,RpgTheme.GOLD);y+=17;var inventory=SheetSections.read(sheet,"inventory");for(var e:InventoryModel.entries(inventory,InventoryModel.Category.ALL,"")){pane.label(e.label()+" × "+e.quantity()+" · "+(e.equipped()?"Equipped":"Carried"),x+2,y,w-4,RpgTheme.TEXT);y+=15;}if(array(inventory,"items").isEmpty())pane.label("No equipment recorded",x+2,y,w-4,RpgTheme.MUTED);
    }
    private static void counter(CharacterCanvas p,Actions a,String key,RpgRecords.Action action,int value,int min,int max,int x,int y,boolean plusAllowed){for(int delta:List.of(-1,1)){var b=p.control(key+":"+delta,new RpgButton(x+(delta>0?20:0),y,18,18,delta<0?"−":"+","",()->{if(a!=null)a.track(new RpgRecords.Change(action,"trackers","",0,(int)Math.clamp((long)value+delta,min,max)));}).accessible((delta<0?"Decrease ":"Increase ")+key).hint("Manual count only. Campaign Inspiration awards require DM permission."));b.active=a!=null&&a.trackable("trackers")&&(delta<0?value>min:plusAllowed&&value<max);}}
    public static String resourceSummary(JsonObject t){var parts=new ArrayList<String>();for(var raw:array(t,"hitDice")){var d=raw.getAsJsonObject();parts.add("d"+text(d,"sides")+" "+text(d,"current")+"/"+text(d,"maximum"));}for(var raw:array(t,"resources")){var p=raw.getAsJsonObject();parts.add(text(p,"name")+" "+text(p,"current")+"/"+text(p,"maximum"));}return parts.isEmpty()?"No pools":String.join(" · ",parts);}
    private static String conditions(JsonObject sheet){return array(SheetSections.read(sheet,"features"),"entries").asList().stream().map(JsonElement::getAsJsonObject).filter(f->Set.of("CONDITION","TEMPORARY").contains(text(f,"kind"))).map(f->text(f,"name")).reduce((a,b)->a+", "+b).orElse("No conditions");}
    private static List<FeatureReference.Entry> notable(JsonObject sheet){var out=new ArrayList<FeatureReference.Entry>();for(var f:array(SheetSections.read(sheet,"features"),"entries"))out.add(FeatureReference.recorded(f.getAsJsonObject()));String name=CreationRules.clazz(sheet).toLowerCase(Locale.ROOT);FeatureReference.classFeatures(name).stream().filter(f->f.level()<=CreationRules.level(sheet)).forEach(out::add);return List.copyOf(out);}
    private static String combatNames(JsonObject sheet){try{var d=SrdAuthoring.data(sheet);var names=new ArrayList<String>();names.add("Unarmed");for(var e:array(d,"weapons"))names.add(e.getAsString().replace('_',' '));return String.join(" · ",names);}catch(RuntimeException e){return "Profile attacks";}}
    private static String combatInformation(JsonObject sheet,JsonObject encounter,JsonObject snapshot){var out=new StringBuilder("Use existing encounter controls for authorized attacks. Sheet inventory does not grant weapons or effects.\n");try{var d=SrdAuthoring.data(sheet);var weapons=new LinkedHashSet<String>();weapons.add("UNARMED");for(var v:array(d,"weapons"))weapons.add(v.getAsString().toUpperCase(Locale.ROOT));for(String name:weapons){var weapon=SrdEquipment.Weapon.valueOf(name);out.append(name.replace('_',' ')).append(" · base ").append(weapon.dice==0?weapon.flat:weapon.dice+"d"+weapon.sides).append(' ').append(weapon.damageType).append(weapon.ranged?" · "+weapon.normalRangeFeet+"/"+weapon.longRangeFeet+" ft":"").append('\n');}for(String key:List.of("armor","arrows","bolts","daggers","resistances","immunities","vulnerabilities","armor_proficiencies","weapon_proficiencies"))if(d.has(key))out.append(key.replace('_',' ')).append(": ").append(d.get(key)).append('\n');if(encounter!=null&&!text(snapshot,"bound").isBlank()&&text(snapshot,"bound").equals(text(encounter,"active")))out.append("Current turn: action ").append(flag(encounter,"actionUsed")?"spent":"available").append(" · movement ").append(text(encounter,"remainingFeet")).append(" ft\n");}catch(RuntimeException ignored){}return out.toString();}
    private static String shown(String s){return s.isBlank()?"Not set":s;}
    private static String signed(int n){return (n>=0?"+":"")+n;}
}
